-- Seed for market_intelligence.public_projects (migration 030). 6 projects, 6 status events, every fact cited to ARY, Geo or APP. Run the 2 statements one at a time, then the check.

INSERT INTO market_intelligence.public_projects (slug, name, category, region, province, agencies, summary, cost_pkr_bn, original_target, keywords, source_url, source_kind)
VALUES
('margalla-motorway-link','Margalla Road to Motorway link','ROADS','Islamabad / Rawalpindi','Islamabad Capital Territory and Punjab','CDA (Islamabad section); Punjab government (2.5 km section)','2.7 km link from Margalla Road to the Motorway, with an interchange on GT Road at Sangjani, two underpasses and a bridge. Three lanes each way plus a two-lane service road. A further 2.5 km section is to be built by the Punjab government.',NULL,DATE '2026-12-31',ARRAY['margalla road','sangjani']::text[],'https://www.app.com.pk/national/mega-project-launched-to-link-margalla-road-directly-to-motorway-for-citizens-convenience/','MEDIA'),
('rawalpindi-ring-road','Rawalpindi Ring Road','ROADS','Rawalpindi','Punjab','RDA','Ring road giving direct connectivity between the Motorway and GT Road. Meant to ease congestion in the twin cities and to serve travellers from Khyber Pakhtunkhwa to Punjab.',35.00,NULL,ARRAY['rawalpindi ring road']::text[],'https://www.app.com.pk/domestic/work-on-rawalpindi-ring-road-progressing-rapidly-nearing-completion-rda-dg/','MEDIA'),
('m6-hyderabad-sukkur-motorway','M-6 Hyderabad-Sukkur Motorway','ROADS','Hyderabad to Sukkur','Sindh','NHA. Loans from Islamic Development Bank and OPEC Fund; sections I-II on a public-private partnership with ADB advice','306 km six-lane motorway in five sections: Hyderabad-Tando Adam, Tando Adam-Nawabshah, Nawabshah-Naushehro Feroz, Naushehro Feroz-Ranipur and Ranipur-Sukkur. Land for the main corridor is acquired.',359.00,NULL,ARRAY['m-6','m6 motorway','sukkur-hyderabad','hyderabad-sukkur','sukkur hyderabad']::text[],'https://arynews.tv/motorway-m-6-work-begin-november-aleem-khan','MEDIA'),
('ml1-karachi-rohri','ML-1 railway, Karachi-Rohri section','TRANSIT','Karachi to Rohri','Sindh','Ministry of Railways','Upgrade of the Karachi-Rohri section of the ML-1 main railway line.',NULL,NULL,ARRAY['ml-1','ml1']::text[],'https://www.geo.tv/latest/641853-ml-1-project-karachi-rohri-section-likely-to-open-next-year-says-minister','MEDIA'),
('apni-chhat-apna-ghar','Apni Chhat Apna Ghar','HOUSING_PROGRAMME','Punjab','Punjab','Punjab government','Interest-free housing loans for low-income families in Punjab to build their own homes.',NULL,NULL,ARRAY['apni chhat','apni chat','apna ghar']::text[],'https://arynews.tv/apni-chhat-apna-ghar-programme-achieves-another-milestone','MEDIA'),
('budget-2026-27-property-tax','Budget 2026-27: property withholding tax','POLICY_TAX','Pakistan (federal)',NULL,'Finance Ministry / FBR','Budget 2026-27 cut the filer withholding tax on property purchase from 2.5% to 1.25% and on sale from 5.5% to 2.75%, as reported from the Finance Minister''s speech. Check the Finance Act for section numbers and the start date.',NULL,NULL,ARRAY['property tax','stamp duty']::text[],'https://arynews.tv/filers-incentives-in-budget-2026-27','MEDIA')
ON CONFLICT (slug) DO NOTHING;

INSERT INTO market_intelligence.project_status_events (project_id, status, target_date, note, event_date, source_url, source_kind)
SELECT p.id, v.status, v.target_date, v.note, v.event_date, v.source_url, 'MEDIA'
FROM (VALUES
('margalla-motorway-link',DATE '2026-05-05','UNDER_CONSTRUCTION',DATE '2026-12-31','Interior Minister inspected the works. Deadline for the Sangjani Interchange is 31 July; the full project is expected by December 2026.','https://www.app.com.pk/national/mega-project-launched-to-link-margalla-road-directly-to-motorway-for-citizens-convenience/'),
('rawalpindi-ring-road',DATE '2025-10-27','UNDER_CONSTRUCTION',NULL,'RDA Director General: over 75% complete and nearing completion; heavy rain delayed work. No completion date given.','https://www.app.com.pk/domestic/work-on-rawalpindi-ring-road-progressing-rapidly-nearing-completion-rda-dg/'),
('m6-hyderabad-sukkur-motorway',DATE '2026-10-04','TENDERED',NULL,'Work scheduled to begin November 2026. Tender for sections I-II planned 6 Nov 2026, bids due 30 Dec 2026, concession award targeted 4 Feb 2027. Land acquisition for the main corridor is complete.','https://arynews.tv/motorway-m-6-work-begin-november-aleem-khan'),
('ml1-karachi-rohri',DATE '2025-12-28','PLANNED',NULL,'Minister said groundwork was expected to begin in July 2026. We found no later update; check Pakistan Railways.','https://www.geo.tv/latest/641853-ml-1-project-karachi-rohri-section-likely-to-open-next-year-says-minister'),
('apni-chhat-apna-ghar',DATE '2026-06-30','ONGOING',NULL,'166,000 loans and Rs215.76 billion released; 105,594 houses completed and 28,453 under construction; over 1.2 million applications.','https://arynews.tv/apni-chhat-apna-ghar-programme-achieves-another-milestone'),
('budget-2026-27-property-tax',DATE '2026-06-13','ANNOUNCED',NULL,'Announced in the budget speech. Not yet checked against the Finance Act.','https://arynews.tv/filers-incentives-in-budget-2026-27')
) AS v(slug, event_date, status, target_date, note, source_url)
JOIN market_intelligence.public_projects p ON p.slug = v.slug
ON CONFLICT (project_id, event_date, status) DO NOTHING;

SELECT (SELECT count(*) FROM market_intelligence.public_projects) AS projects, (SELECT count(*) FROM market_intelligence.project_status_events) AS events;
